#include <omp.h>
#include <vector>
#include <algorithm>

double sumOfMinimumElements(std::vector<double> const& x, std::vector<double> const& y) {
    // Use the length of the shorter vector to avoid out‑of‑range access
    size_t n = std::min(x.size(), y.size());

    double sum = 0.0;

    // Parallel reduction to avoid data races
    #pragma omp parallel for reduction(+:sum) schedule(static)
    for (size_t i = 0; i < n; ++i) {
        sum += std::min(x[i], y[i]);
    }

    return sum;
}
